def construct_sequence():
    # t_0 = 0
    # t_i = 2i - 1 for i >= 1
    T = [0]
    for i in range(1, 87):
        t_i = 2 * i - 1
        T.append(t_i)
    return T

def calculate_sum_set_size(T):
    N = len(T)
    S = set()
    for i in range(N):
        for j in range(i, N):
            S.add(T[i] + T[j])
    return len(S)

T_sequence = construct_sequence()
size_S = calculate_sum_set_size(T_sequence)

